import 'dart:convert';import 'dart:io';import 'package:flutter/material.dart';import 'package:flutter_test/flutter_test.dart';import 'package:flutter_core/application_modules.dart';import 'package:flutter_core/component_catalogue/prime_component_catalogue.dart';
final scope=PreferenceScope('tenant','actor','registered-role','live');
Map<String,Object?> data(String module)=>{'scope':scope.toJson(),'module':module,'items':[{'id':'current-record','version':1,'title':'Registered account record','body':'Overview','date':'','lane':'','meta':'','actions':module=='settings'?<Map<String,Object?>>[{'id':'edit','label':'Edit fixture','fields':['body'],'target':''}]:<Map<String,Object?>>[]}],'lanes':<Map<String,Object?>>[],'offset':0,'total':1,'partial':false};
class Port implements WorkPort{final String module;Port(this.module);@override Future<Object?> read(WorkQuery q)async=>data(module);@override Future<WorkReceipt> mutate(WorkCommand c,String key)async=>throw const WorkFailure('unavailable');@override Future<Object?> readItem(String id)async=>data(module);@override void dispose(){}}
void main(){final raw=jsonDecode(File('../primecare_ui/catalogs/application-modules.registration.json').readAsStringSync()),labels=CatalogueLabels.fromMetadata(raw,'en');
 for(final module in ['academy','commerce','ai-images','profile','settings','help']){testWidgets('$module renders only an approved port or unavailable state',(t)async{await t.binding.setSurfaceSize(const Size(1200,1600));addTearDown(()=>t.binding.setSurfaceSize(null));final connected=['profile','settings'].contains(module),session=WorkModuleSession(scope,module,port:connected?Port(module):null,requestId:()=> '00000000-0000-4000-8000-000000000001');await t.pumpWidget(MaterialApp(home:Scaffold(body:SingleChildScrollView(child:PrimeWorkModule(labels:labels,session:session,scope:'actor',year:2026,month:11,gap:8,boardWidth:250)))));await t.pumpAndSettle();expect(t.takeException(),isNull);expect(t.widget<TextButton>(find.widgetWithText(TextButton,labels.text('create')).first).onPressed,isNull);if(connected){expect(find.text('Overview'),findsOneWidget);await t.tap(find.widgetWithText(TextButton,labels.text('open')).first);await t.pumpAndSettle();expect(find.text(labels.text('success')),findsNothing);if(module=='profile')expect(find.widgetWithText(TextButton,labels.text('save')),findsNothing);}else{expect(session.status,'unavailable');expect(find.text('Registered account record'),findsNothing);}await t.pumpWidget(const SizedBox());session.dispose();});}
 testWidgets('an unavailable mutation rejects and retains the visible settings draft',(t)async{await t.binding.setSurfaceSize(const Size(1200,1600));addTearDown(()=>t.binding.setSurfaceSize(null));final session=WorkModuleSession(scope,'settings',port:Port('settings'),requestId:()=> '00000000-0000-4000-8000-000000000001');await t.pumpWidget(MaterialApp(home:Scaffold(body:SingleChildScrollView(child:PrimeWorkModule(labels:labels,session:session,scope:'actor',year:2026,month:11,gap:8,boardWidth:250)))));await t.pumpAndSettle();await t.tap(find.widgetWithText(TextButton,labels.text('open')).first);await t.pumpAndSettle();await t.enterText(find.byType(TextField).last,'Retained draft');await t.tap(find.widgetWithText(TextButton,labels.text('save')).first);await t.pumpAndSettle();expect(session.status,'unavailable');expect(session.pending,isNotNull);expect(find.text('Retained draft'),findsOneWidget);expect(find.widgetWithText(TextButton,labels.text('save')),findsOneWidget);expect(find.text(labels.text('success')),findsNothing);expect(t.takeException(),isNull);await t.pumpWidget(const SizedBox());session.dispose();});
}
